engine/level.py:
"""
Static level geometry: everything about a puzzle that never changes
while it is played or solved.

A cell is a plain int, ``cell = y * width + x``, so one step is one
addition (UP = -width, DOWN = +width, LEFT = -1, RIGHT = +1). Every
level must be enclosed by walls, which is what makes that arithmetic
safe: a floor cell always has four in-bounds neighbours.

Level text uses the standard XSB symbols:

    #  wall        $  crate            @  keeper
    .  goal        *  crate on goal    +  keeper on goal
    (space, - or _)  floor             ;  comment (the first one is the title)
"""

from .state import State

SYMBOLS = "# -_.$*@+"


class LevelError(ValueError):
    """The level text breaks a rule of Sokoban. The message is shown to players."""


class Level:
    def __init__(self, width, height, walls, goals, floor, title=""):
        self.width, self.height, self.title = width, height, title
        self.walls = frozenset(walls)
        self.goals = frozenset(goals)
        # floor = the cells the keeper could ever stand on (the enclosed interior)
        self.floor = frozenset(floor)
        self.steps = {"U": -width, "D": width, "L": -1, "R": 1}
        self.names = {step: name for name, step in self.steps.items()}
        self.neighbours = {cell: tuple(cell + step for step in self.names
                                       if cell + step in self.floor)
                           for cell in self.floor}

    def xy(self, cell):
        return cell % self.width, cell // self.width


def parse_level(text, title=""):
    """Turn XSB text into ``(Level, State)``, or raise LevelError saying why not."""
    rows = []
    for line in text.splitlines():
        if line.lstrip().startswith(";"):
            title = title or line.strip(" ;\t")
        elif line.strip():
            rows.append(line.rstrip())
    if not rows:
        raise LevelError("The level is empty.")

    width, height = max(map(len, rows)), len(rows)
    walls, goals, boxes, keepers = set(), set(), set(), []
    for y, row in enumerate(rows):
        for x, symbol in enumerate(row):
            cell = y * width + x
            if symbol not in SYMBOLS:
                raise LevelError(f"Unknown symbol {symbol!r} in row {y + 1}.")
            if symbol == "#":
                walls.add(cell)
            if symbol in ".*+":
                goals.add(cell)
            if symbol in "$*":
                boxes.add(cell)
            if symbol in "@+":
                keepers.append(cell)

    if len(keepers) != 1:
        raise LevelError(f"A level needs exactly one keeper, found {len(keepers)}.")
    if not boxes:
        raise LevelError("A level needs at least one crate.")
    if len(boxes) != len(goals):
        raise LevelError(f"{len(boxes)} crates but {len(goals)} goals: "
                         "the counts must match.")

    floor = _interior(keepers[0], walls, width, height)
    if not boxes <= floor:
        raise LevelError("A crate is walled off from the keeper.")
    if not goals <= floor:
        raise LevelError("A goal is walled off from the keeper.")

    return (Level(width, height, walls, goals, floor, title),
            State(keepers[0], frozenset(boxes)))


def _interior(start, walls, width, height):
    """Flood-fill from the keeper; leaking to the edge means a missing wall."""
    seen, stack = {start}, [start]
    while stack:
        cell = stack.pop()
        x, y = cell % width, cell // width
        if x in (0, width - 1) or y in (0, height - 1):
            raise LevelError("The level is not enclosed by walls.")
        for neighbour in (cell - width, cell + width, cell - 1, cell + 1):
            if neighbour not in seen and neighbour not in walls:
                seen.add(neighbour)
                stack.append(neighbour)
    return seen


def format_level(level, state):
    """The XSB text of a position: the inverse of parse_level."""
    rows = []
    for y in range(level.height):
        row = ""
        for cell in range(y * level.width, (y + 1) * level.width):
            goal = cell in level.goals
            if cell in level.walls:
                row += "#"
            elif cell in state.boxes:
                row += "*" if goal else "$"
            elif cell == state.player:
                row += "+" if goal else "@"
            else:
                row += "." if goal else " "
        rows.append(row.rstrip())
    return "\n".join(rows)

solvers/deadlock.py:
"""
Deadlock detection: the knowledge-based layer.

A deadlock is a position from which the puzzle can never be solved,
whatever happens next. Each rule below is a logical rule of the form
"IF <pattern around a crate> THEN <unsolvable>". All of them are
*sound*: they only fire on positions that are truly lost, so pruning
with them can never throw away a solution (tests/test_solvers.py checks
this against exhaustive search).

Static rules (depend only on the level, precomputed once as a map of
"dead squares" a crate must never be pushed onto):

    corner      a wall on one horizontal AND one vertical side
    wall-line   the crate can only slide along a wall, and that whole
                stretch of wall holds no goal
    no-path     the general case: no sequence of pushes brings a crate
                from here to any goal (found by pulling crates backwards
                from the goals, see heuristics.push_distances)

Dynamic rule (depends on the other crates, checked after every push):

    freeze      crates that block each other so that none can ever move
                again, with at least one of them off-goal

"matching" is listed for completeness: it is detected by the matching
heuristic, not here.
"""

from .heuristics import push_distances

RULES = {
    "corner": ("Corner trap",
               "A crate wedged into a corner can never be pushed again."),
    "wall-line": ("Wall-line trap",
                  "Against this wall the crate can only slide sideways, "
                  "and no goal lies anywhere along it."),
    "no-path": ("Dead square",
                "No sequence of pushes can bring a crate from this square to any goal."),
    "freeze": ("Freeze deadlock",
               "These crates block each other. None of them can ever move again."),
    "matching": ("No assignment",
                 "The crates cannot each reach a goal of their own."),
}


def corner_squares(level):
    floor, w = level.floor, level.width
    return {c for c in floor - level.goals
            if (c - w not in floor or c + w not in floor)
            and (c - 1 not in floor or c + 1 not in floor)}


def wall_line_squares(level):
    """Cells on a straight run of floor that is closed at both ends, has a
    wall beside every cell (so a crate can never leave the line) and
    contains no goal."""
    floor, dead = level.floor, set()
    for along, across in ((1, level.width), (level.width, 1)):
        for start in floor:
            if start - along in floor:
                continue                        # not the first cell of its run
            run = [start]
            while run[-1] + along in floor:
                run.append(run[-1] + along)
            pinned = all(c - across not in floor or c + across not in floor for c in run)
            if pinned and not level.goals.intersection(run):
                dead.update(run)
    return dead


class Deadlocks:
    """The rules, precomputed for one level."""

    def __init__(self, level):
        self.level = level
        alive = set().union(*push_distances(level).values())
        corners, lines = corner_squares(level), wall_line_squares(level)
        # dead square -> the most specific rule that explains it
        self.dead = {cell: "corner" if cell in corners
                     else "wall-line" if cell in lines else "no-path"
                     for cell in level.floor - alive}

    def after_push(self, boxes, box):
        """The rule broken by the crate just pushed onto `box`, or None.
        Assumes the position before the push was not already deadlocked."""
        if box in self.dead:
            return self.dead[box]
        cluster = self.frozen(boxes, box)
        if cluster and not cluster <= self.level.goals:
            return "freeze"
        return None

    def check_state(self, boxes):
        """``(rule, crates involved)`` for a whole position, or None."""
        for box in boxes:
            if box in self.dead:
                return self.dead[box], frozenset({box})
        for box in boxes:
            cluster = self.frozen(boxes, box)
            if cluster and not cluster <= self.level.goals:
                return "freeze", frozenset(cluster)
        return None

    def frozen(self, boxes, box, assumed=None):
        """The set of crates proven immovable together with `box`, or None
        if `box` can still move.

        A crate is frozen when it is blocked along both axes. An axis is
        blocked by a wall on either side, by dead squares on both sides,
        or by a neighbouring crate that is itself frozen. Crates already
        on the current chain of reasoning (`assumed`) count as walls;
        that is what lets a ring of crates that hold each other in place
        be recognised.
        """
        floor = self.level.floor
        assumed = (assumed or frozenset()) | {box}
        cluster = {box}
        for axis in (1, self.level.width):
            a, b = box - axis, box + axis
            if a not in floor or b not in floor:
                continue                                    # wall
            if a in self.dead and b in self.dead:
                continue                                    # nowhere safe to go
            for neighbour in (a, b):
                if neighbour in boxes:
                    held = (set() if neighbour in assumed
                            else self.frozen(boxes, neighbour, assumed))
                    if held is not None:
                        cluster |= held
                        break
            else:
                return None                                 # this axis is free
        return cluster

interface/bridge.py:
"""
The bridge: everything the browser can ask Python to do.

    call("move", '{"direction": "L"}')  ->  '{"player": 17, "boxes": [...], ...}'

A Game holds one play session:

*   the level and a **timeline** of positions. Your moves and the AI's
    solution live on the same line, so undo, redo, replay and scrubbing
    are all just "move the cursor";
*   **jobs**: searches that run a few milliseconds at a time whenever
    the page calls tick(), so the board keeps animating while BFS
    grinds and several algorithms can race each other.

Nothing here touches the browser; tests drive it directly.
"""

import json

from analytics.benchmark import Benchmark
from analytics.report import summary, to_csv, to_markdown
from engine.level import LevelError, format_level, parse_level
from engine.state import apply_move, is_goal
from puzzles.generator import generate
from puzzles.library import PACKS, catalog
from solvers.compare import Race, compare_to_baseline
from solvers.deadlock import RULES, Deadlocks
from solvers.solve import ALGORITHMS, BEST, Search

# Budget per search in the browser, where Python runs a few times slower.
NODE_LIMIT, TIME_LIMIT = 200_000, 20.0


class Game:
    def __init__(self):
        self.levels = {entry["id"]: entry for entry in catalog()}
        self.jobs = {}
        self.rows = []              # benchmark rows of the last run
        self.level = None

    # ------------------------------------------------------------ catalogue

    def boot(self):
        return {
            "algorithms": [{"key": key, **algo._asdict()} for key, algo in ALGORITHMS.items()],
            "packs": [{"key": key, "name": name} for key, name in PACKS.items()],
            "levels": [{k: e[k] for k in ("id", "pack", "title", "note")}
                       for e in self.levels.values()],
            "rules": {key: {"name": name, "why": why} for key, (name, why) in RULES.items()},
            "best": BEST,
        }

    # -------------------------------------------------------------- playing

    def open(self, id=None, text=None, title="Custom level"):
        """Start a level from the catalogue (`id`) or from XSB `text`."""
        entry = self.levels[id] if id else {"id": None, "pack": None, "note": "", "title": title}
        self.level, start = parse_level(entry.get("text", text), "" if id else title)
        self.entry = entry
        self.rules = Deadlocks(self.level)
        self.states, self.moves, self.cursor = [start], "", 0
        self.ai_from = None         # timeline index where the AI's moves begin
        self.hints = 0
        self.par = None             # the AI's optimum from the start position
        # a new level ends the searches on the old one; a running benchmark carries on
        self.jobs = {name: job for name, job in self.jobs.items() if name == "bench"}
        self.jobs["par"] = Search(self.level, start, BEST, NODE_LIMIT, 5.0)
        level = self.level
        return {**self.view(), "level": {
            "id": entry["id"], "pack": entry["pack"], "note": entry["note"],
            "title": level.title or entry["title"],
            "width": level.width, "height": level.height, "crates": len(start.boxes),
            "walls": sorted(level.walls), "goals": sorted(level.goals),
            "floor": sorted(level.floor), "dead": self.rules.dead,
            "text": format_level(level, start),
        }}

    def view(self):
        """The current position and everything the sidebar shows about it."""
        state = self.states[self.cursor]
        played = self.moves[:self.cursor]
        deadlock = self.rules.check_state(state.boxes)
        if deadlock:
            rule, crates = deadlock
            name, why = RULES[rule]
            deadlock = {"rule": rule, "name": name, "why": why, "crates": sorted(crates)}
        return {
            "player": state.player, "boxes": sorted(state.boxes),
            "cursor": self.cursor, "length": len(self.moves), "moves": self.moves,
            "pushes": sum(move.isupper() for move in played),
            "last": played[-1:], "solved": is_goal(self.level, state),
            "ai_from": self.ai_from, "hints": self.hints, "deadlock": deadlock,
        }

    def move(self, direction):
        """One keeper step. A blocked step changes nothing."""
        result = apply_move(self.level, self.states[self.cursor], direction)
        if result:
            state, pushed = result
            self._extend(direction.upper() if pushed else direction.lower(), [state])
            self.cursor += 1
        return self.view()

    def _extend(self, moves, states):
        """Replace everything after the cursor with `moves`."""
        del self.states[self.cursor + 1:]
        self.moves = self.moves[:self.cursor] + moves
        self.states += states
        if self.ai_from is not None and self.ai_from > self.cursor:
            self.ai_from = None
        self.jobs.pop("solve", None)
        self.jobs.pop("hint", None)

    def seek(self, cursor):
        self.cursor = max(0, min(int(cursor), len(self.moves)))
        return self.view()

    def undo(self):
        return self.seek(self.cursor - 1)

    def redo(self):
        return self.seek(self.cursor + 1)

    def reset(self):
        self.hints = 0
        return self.seek(0)

    def trails(self):
        """Cells walked by you so far, and by the AI's optimal solution."""
        ai, state = [], self.states[0]
        if self.par and self.par["solved"]:
            ai = [state.player]
            for move in self.par["moves"]:
                state = apply_move(self.level, state, move)[0]
                ai.append(state.player)
        return {"you": [s.player for s in self.states[:self.cursor + 1]], "ai": ai}

    # ------------------------------------------------------------------- AI

    def solve(self, algorithm=BEST):
        """Search from the current position; the solution joins the timeline."""
        self.jobs["solve"] = Search(self.level, self.states[self.cursor], algorithm,
                                    NODE_LIMIT, TIME_LIMIT)
        return {"started": "solve"}

    def hint(self):
        """Find the best next push from the current position."""
        self.hints += 1
        self.jobs["hint"] = Search(self.level, self.states[self.cursor], BEST, NODE_LIMIT, 8.0)
        return {"started": "hint"}

    def race(self):
        """All algorithms from the level's start position, side by side."""
        self.jobs["race"] = Race(self.level, self.states[0],
                                 node_limit=NODE_LIMIT, time_limit=TIME_LIMIT)
        return {"started": "race"}

    def benchmark(self, pack=None, seconds=3.0):
        """Every algorithm on every level of `pack` (all packs if None),
        each search limited to `seconds`."""
        levels = [e for e in self.levels.values() if pack in (None, e["pack"])]
        self.rows = []
        self.jobs["bench"] = Benchmark(levels, node_limit=NODE_LIMIT,
                                       time_limit=min(float(seconds), 30.0))
        return {"started": "bench", "total": len(levels)}

    def report(self, format="csv"):
        return (to_markdown if format == "markdown" else to_csv)(self.rows)

    def cancel(self, job):
        self.jobs.pop(job, None)
        return {"cancelled": job}

    def tick(self, ms=10):
        """Share `ms` milliseconds between the running jobs and report on each.
        A finished job is reported once, then forgotten."""
        reports = {}
        share = ms / 1000 / max(len(self.jobs), 1)
        for name, job in list(self.jobs.items()):
            done = job.advance(share)
            if name not in self.jobs:
                continue                    # replaced or cancelled meanwhile
            reports[name] = getattr(self, f"_report_{name}")(job, done)
            reports[name]["done"] = done
            if done:
                self.jobs.pop(name, None)
        return {"jobs": reports}

    def _report_par(self, search, done):
        if done:
            self.par = search.result
        return _progress(search)

    def _report_solve(self, search, done):
        report = _progress(search)
        if done and search.result["solved"]:
            moves, state, states = search.result["moves"], self.states[self.cursor], []
            for move in moves:
                state = apply_move(self.level, state, move)[0]
                states.append(state)
            self._extend(moves, states)
            self.ai_from = self.cursor
        if done:
            report["view"] = self.view()
        return report

    def _report_hint(self, search, done):
        report = _progress(search)
        if done and search.result["solved"] and search.result["moves"]:
            moves = search.result["moves"]
            first_push = next(i for i, move in enumerate(moves) if move.isupper())
            state = self.states[self.cursor]
            path = [state.player]
            for move in moves[:first_push]:
                state = apply_move(self.level, state, move)[0]
                path.append(state.player)
            step = self.level.steps[moves[first_push]]
            report["hint"] = {"moves": moves[:first_push + 1], "path": path,
                              "box": state.player + step, "to": state.player + 2 * step}
        return report

    def _report_race(self, race, done):
        if done:
            compare_to_baseline(race.results)
        return {"lanes": [_progress(search) for search in race.searches]}

    def _report_bench(self, bench, done):
        fresh = bench.rows[len(self.rows):]
        self.rows = list(bench.rows)
        report = {"rows": [_without_moves(row) for row in fresh],
                  "finished": bench.total - len(bench.pending) - (bench.race is not None),
                  "total": bench.total,
                  "current": bench.entry["title"] if bench.entry else ""}
        if done:
            report["summary"] = summary(self.rows)
        return report

    # --------------------------------------------------------------- editor

    def check(self, text):
        """Validate level text without starting it (LevelError says what is wrong)."""
        level, state = parse_level(text)
        return {"crates": len(state.boxes), "width": level.width, "height": level.height}

    def generate(self, seed=0, width=9, height=8, boxes=3):
        width, height = _clamp(width, 6, 12), _clamp(height, 6, 10)
        boxes = _clamp(boxes, 1, min(5, (width - 2) * (height - 2) // 6))
        return {"text": generate(int(seed), width, height, boxes)}


def _clamp(value, low, high):
    return max(low, min(int(value), high))


def _without_moves(result):
    return {key: value for key, value in result.items() if key != "moves"}


def _progress(search):
    """A search's live counters, plus its result once it has one."""
    stats = search.stats
    state = stats["state"]
    report = {
        "algorithm": search.algorithm,
        "label": ALGORITHMS[search.algorithm].label,
        "stats": {
            "expanded": stats["expanded"], "generated": stats["generated"],
            "frontier": stats["frontier"], "depth": stats["depth"],
            "pruned": sum(stats["pruned"].values()), "time": search.elapsed,
            "player": state.player, "boxes": sorted(state.boxes),
        },
    }
    if search.result:
        report["result"] = search.result
    return report


GAME = Game()


def call(method, payload="{}"):
    """JSON door used by the page: ``call(name, json_arguments) -> json``.
    Problems come back as ``{"error": message}`` instead of exceptions."""
    try:
        if method.startswith("_") or not callable(getattr(Game, method, None)):
            raise LevelError(f"Unknown request: {method}")
        return json.dumps(getattr(GAME, method)(**json.loads(payload)))
    except LevelError as problem:
        return json.dumps({"error": str(problem)})
    except KeyError as missing:
        return json.dumps({"error": f"Unknown level: {missing}"})
